var r={en:`An accepted order must persist and trigger billing, inventory and reports. Consumers retry and read models may lag, but no accepted order can vanish.`,ua:`Прийняте замовлення має зберегтися й запустити оплату, склад та звіти. Споживачі повторюють роботу, проєкції можуть відставати, але прийняте замовлення не зникає.`};var n={en:[`Draw command handling, transactional state/outbox, publisher and broker.`,`Add consumers, read projection, retry and dead-letter paths.`,`Define event IDs, ordering, idempotency and crash recovery.`],ua:[`Намалюй обробку команди, транзакційний стан/outbox, публікатор і брокер.`,`Додай споживачів, проєкції, повтори й dead-letter.`,`Визнач ID подій, порядок, ідемпотентність і відновлення після аварії.`]};var t=[{en:`State and outbound event share an atomic persistence boundary.`,ua:`Стан і вихідна подія мають спільне атомарне зберігання.`},{en:`Failed consumers have bounded retry and recovery paths.`,ua:`Невдалі споживачі мають обмежені повтори й відновлення.`}];var d={scenario:r,tasks:n,checks:t};export{t as checks,d as default,r as scenario,n as tasks};